<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class AlumniController extends Controller
{
 private function schoolId(): int { return (int) session('school_id', 1); }
 public function dashboard() { $q=DB::table('alumni_profiles')->where('school_id',$this->schoolId()); return view('alumni.dashboard',['total'=>(clone $q)->count(),'active'=>(clone $q)->where('status','active')->count(),'recent'=>(clone $q)->latest()->limit(6)->get()]); }
 public function index(Request $request) { $q=DB::table('alumni_profiles')->where('school_id',$this->schoolId()); if($request->filled('search')) $q->where(function($x) use($request) { $x->where('full_name','like','%'.$request->search.'%'); }); if($request->filled('status')) $q->where('status',$request->status); $items=$q->latest()->paginate(15)->withQueryString(); return view('alumni.index',compact('items')); }
 public function create() { $campuses=DB::table('campuses')->where('school_id',$this->schoolId())->orderBy('name')->get(); $staff=DB::table('staff_profiles')->where('school_id',$this->schoolId())->whereNull('deleted_at')->orderBy('first_name')->get(); return view('alumni.create',compact('campuses','staff')); }
 public function store(Request $request) { $data=$request->validate(['full_name'=>'required|string|max:255','email'=>'nullable|email|max:255','phone'=>'nullable|string|max:40','admission_number'=>'nullable|string|max:100','graduation_year'=>'nullable|string|max:20','course_or_class'=>'nullable|string|max:255','current_organization'=>'nullable|string|max:255','designation'=>'nullable|string|max:255','city'=>'nullable|string|max:255','linkedin_url'=>'nullable|url|max:255','status'=>'required|in:active,inactive','notes'=>'nullable|string']); $data['school_id']=$schoolId; DB::table('alumni_profiles')->insert($data+['created_at'=>now(),'updated_at'=>now()]); return redirect()->route('alumni.index')->with('success','Record created successfully.'); }
 public function show(int $id) { $item=DB::table('alumni_profiles')->where('school_id',$this->schoolId())->find($id); abort_unless($item,404); return view('alumni.show',compact('item')); }
 public function edit(int $id) { $item=DB::table('alumni_profiles')->where('school_id',$this->schoolId())->find($id); abort_unless($item,404); $campuses=DB::table('campuses')->where('school_id',$this->schoolId())->orderBy('name')->get(); $staff=DB::table('staff_profiles')->where('school_id',$this->schoolId())->whereNull('deleted_at')->orderBy('first_name')->get(); return view('alumni.edit',compact('item','campuses','staff')); }
 public function update(Request $request,int $id) { $item=DB::table('alumni_profiles')->where('school_id',$this->schoolId())->find($id); abort_unless($item,404); $data=$request->validate(['full_name'=>'required|string|max:255','email'=>'nullable|email|max:255','phone'=>'nullable|string|max:40','admission_number'=>'nullable|string|max:100','graduation_year'=>'nullable|string|max:20','course_or_class'=>'nullable|string|max:255','current_organization'=>'nullable|string|max:255','designation'=>'nullable|string|max:255','city'=>'nullable|string|max:255','linkedin_url'=>'nullable|url|max:255','status'=>'required|in:active,inactive','notes'=>'nullable|string']); $data['school_id']=$schoolId; $data['updated_at']=now(); DB::table('alumni_profiles')->where('id',$id)->where('school_id',$this->schoolId())->update($data); return redirect()->route('alumni.show',$id)->with('success','Record updated successfully.'); }
 public function destroy(int $id) { $deleted=DB::table('alumni_profiles')->where('school_id',$this->schoolId())->where('id',$id)->delete(); abort_unless($deleted,404); return redirect()->route('alumni.index')->with('success','Record deleted successfully.'); }
}
